import { Fragment } from "react";
import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Link,
  Section,
  Row,
  Column,
  Img,
  Tailwind,
} from "react-email";

import { DefaultFonts } from "@/components/email/font-default";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type HeaderWithLogoAndMenuVariant =
  | "menu-right"
  | "menu-left"
  | "menu-around"
  | "stacked-left"
  | "stacked-center"
  | "stacked-right";

export interface HeaderMenuLink {
  href: string;
  label: string;
}

export interface HeaderWithLogoAndMenuProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  links?: HeaderMenuLink[];
  pageBackgroundColor?: string;
  backgroundColor?: string;
  textColor?: string;
  variant?: HeaderWithLogoAndMenuVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = [
  "@media only screen and (max-width: 599px) {",
  "  .header-menu-stack { display: block !important; width: 100% !important; }",
  "  .header-menu-right-links { padding: 24px 0 0 !important; text-align: left !important; }",
  "  .header-menu-right-link { margin-left: 0 !important; margin-right: 24px !important; }",
  "  .header-menu-left-row { display: table !important; width: 100% !important; }",
  "  .header-menu-left-links { display: table-footer-group !important; text-align: right !important; }",
  "  .header-menu-left-logo { display: table-header-group !important; text-align: right !important; }",
  "  .header-menu-left-links-inner { padding-top: 24px !important; }",
  "  .header-menu-around-row { display: table !important; width: 100% !important; }",
  "  .header-menu-around-desktop { display: none !important; }",
  "  .header-menu-around-logo { display: table-header-group !important; width: 100% !important; }",
  "  .header-menu-around-mobile { display: block !important; padding-top: 24px !important; width: 100% !important; }",
  "}",
].join("\n");

const defaultLinks: HeaderMenuLink[] = [
  { href: "https://example.com", label: "Home" },
  { href: "https://example.com/about", label: "About us" },
  { href: "https://example.com/shop", label: "Shop" },
  { href: "https://example.com/faq", label: "FAQs" },
  { href: "https://example.com/returns", label: "Returns" },
  { href: "https://example.com/contact", label: "Contact us" },
];

const defaults = {
  backgroundColor: "#fffffe",
  links: defaultLinks,
  logoAlt: "Maizzle",
  logoHref: "https://example.com",
  logoSrc: emailAsset("maizzle-insignia.png"),
  pageBackgroundColor: "#f1f5f9",
  textColor: "#6b7280",
};

type SectionProps = Omit<HeaderWithLogoAndMenuProps, "theme">;

type ResolvedProps = typeof defaults & SectionProps;

const Logo = ({ props }: { props: ResolvedProps }) => (
  <Link href={props.logoHref}>
    <Img
      alt={props.logoAlt}
      src={props.logoSrc}
      style={{ maxWidth: "100%", verticalAlign: "middle" }}
      width={55}
    />
  </Link>
);

const MenuLinks = ({
  links,
  margin,
  props,
  responsiveClassName,
}: {
  links: HeaderMenuLink[];
  margin: "left" | "right" | "around";
  props: ResolvedProps;
  responsiveClassName?: string;
}) => (
  <>
    {links.map((link, index) => {
      let marginLeft: string | undefined;
      let marginRight: string | undefined;
      if (margin === "left" && index > 0) {
        marginLeft = "24px";
      }
      if (margin === "right") {
        marginRight = "24px";
      }
      if (margin === "around") {
        marginLeft = "12px";
        marginRight = "12px";
      }
      return (
        <Link
          className={responsiveClassName}
          href={link.href}
          key={link.href + link.label}
          style={{
            color: props.textColor,
            display: "inline-block",
            fontFamily,
            fontSize: "14px",
            fontWeight: 500,
            lineHeight: "32px",
            marginLeft,
            marginRight,
            textDecoration: "none",
          }}
        >
          {link.label}
        </Link>
      );
    })}
  </>
);

const MenuRight = ({ props }: { props: ResolvedProps }) => (
  <Section width="100%">
    <Fragment>
      <Row>
        <Column className="header-menu-stack" style={{ width: "55px" }}>
          <Logo props={props} />
        </Column>
        <Column
          className="header-menu-stack header-menu-right-links"
          style={{
            fontSize: 0,
            paddingLeft: "24px",
            textAlign: "right",
          }}
        >
          <MenuLinks
            links={props.links}
            margin="left"
            props={props}
            responsiveClassName="header-menu-right-link"
          />
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const MenuLeft = ({ props }: { props: ResolvedProps }) => (
  <Section className="header-menu-left-row" width="100%">
    <Fragment>
      <Row>
        <Column
          className="header-menu-left-links"
          style={{ paddingRight: "24px", textAlign: "left" }}
        >
          <Section
            className="header-menu-left-links-inner"
            style={{ fontSize: 0 }}
          >
            <MenuLinks links={props.links} margin="left" props={props} />
          </Section>
        </Column>
        <Column
          className="header-menu-left-logo"
          style={{ textAlign: "right", width: "55px" }}
        >
          <Logo props={props} />
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const MenuAround = ({ props }: { props: ResolvedProps }) => (
  <Section className="header-menu-around-row" width="100%">
    <Fragment>
      <Row>
        <Column
          className="header-menu-around-desktop"
          style={{ fontSize: 0, textAlign: "left" }}
        >
          <MenuLinks
            links={props.links.slice(0, 3)}
            margin="left"
            props={props}
          />
        </Column>
        <Column
          className="header-menu-around-logo"
          style={{ textAlign: "center", width: "55px" }}
        >
          <Logo props={props} />
        </Column>
        <Column
          className="header-menu-around-mobile"
          style={{ display: "none", fontSize: 0, textAlign: "center" }}
        >
          <MenuLinks links={props.links} margin="around" props={props} />
        </Column>
        <Column
          className="header-menu-around-desktop"
          style={{ fontSize: 0, textAlign: "right" }}
        >
          <MenuLinks
            links={props.links.slice(3, 6)}
            margin="left"
            props={props}
          />
        </Column>
      </Row>
    </Fragment>
  </Section>
);

const StackedMenu = ({
  alignment,
  props,
}: {
  alignment: "left" | "center" | "right";
  props: ResolvedProps;
}) => {
  let margin: "left" | "right" | "around" = "left";
  if (alignment === "left") {
    margin = "right";
  } else if (alignment === "center") {
    margin = "around";
  }
  return (
    <Section width="100%">
      <Fragment>
        <Row>
          <Column style={{ textAlign: alignment }}>
            <Section>
              <Logo props={props} />
            </Section>
            <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
            <Section style={{ fontSize: 0 }}>
              <MenuLinks links={props.links} margin={margin} props={props} />
            </Section>
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogoAndMenuSection = (props: SectionProps) => {
  const variant = props.variant ?? "menu-right";
  const resolved = { ...defaults, ...props } as ResolvedProps;
  let content;
  if (variant === "menu-left") {
    content = <MenuLeft props={resolved} />;
  } else if (variant === "menu-around") {
    content = <MenuAround props={resolved} />;
  } else if (variant.startsWith("stacked-")) {
    content = (
      <StackedMenu
        alignment={
          variant.replace("stacked-", "") as "left" | "center" | "right"
        }
        props={resolved}
      />
    );
  } else {
    content = <MenuRight props={resolved} />;
  }
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column style={{ maxWidth: "100%", width: "600px" }}>
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    style={{
                      backgroundColor: resolved.backgroundColor,
                      padding: "24px",
                    }}
                  >
                    {content}
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogoAndMenu = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "menu-right",
  ...props
}: HeaderWithLogoAndMenuProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: responsiveStyles }} />
    </EmailHead>
    <Preview>Home About us Shop FAQs Returns Contact us</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <HeaderWithLogoAndMenuSection
          {...props}
          pageBackgroundColor={pageBackgroundColor}
          variant={variant}
        />
      </Body>
    </Tailwind>
  </Html>
);

HeaderWithLogoAndMenu.PreviewProps = {
  theme: defaultTheme,
  variant: "menu-right",
} satisfies HeaderWithLogoAndMenuProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
